const endpoint = "https://staging.crossmint.com/api/2022-06-09/collections/default/nfts";

const payload = {
  recipient: "email:test@example.com:polygon-amoy",
  metadata: {
    name: "Welcome NFT",
    description: "A welcome gift",
    image: "https://example.com/nft.png",
  },
};

async function mintNft() {
  let output;

  try {
    if (!apiKey) {
      throw new Error("CROSSMINT_API_KEY environment variable is not set");
    }

    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      const errorBody = await response.text().catch(() => "");
      throw new Error(`HTTP ${response.status} ${response.statusText} ${errorBody}`.trim());
    }

    output = await response.json();
  } catch (error) {
    output = { error: error.message };
  }

